<h1>My payments</h1><p>Payment history is read-only. Voided payments remain visible.</p><div style="overflow-x:auto"><table><thead><tr><th>Invoice</th><th>Date</th><th>Amount</th><th>Method</th><th>Reference</th><th>Status</th></tr></thead><tbody><?php foreach($payments as $payment): ?><tr><td><?= htmlspecialchars($payment['invoice_number'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($payment['payment_date'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars(tuman_invoice_money_label($payment['amount'],$payment['currency_code']),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($payment['payment_method'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($payment['reference_number']??'—',ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($payment['status'],ENT_QUOTES,'UTF-8') ?><?= $payment['voided_at']?' '.$payment['voided_at']:'' ?></td></tr><?php endforeach; ?></tbody></table></div><?php if($payments===[]): ?><p>No payments are available.</p><?php endif; ?>
